def holdout3_sha256() -> str:
    return hashlib.sha256(Path(__file__).read_bytes().replace(b'\r\n', b'\n')).hexdigest()


if __name__ == '__main__':
    from .dataset import check_task
    for row in map(check_task, HOLDOUT3):
        print(row['id'], row['status'], row.get('reason', row.get('seconds', '')), flush=True)
